selector_to_html = {"a[href=\"#pyskyfire.common.meridional.MeridionalPassage.wall_tangents\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.wall_tangents\">\n<span class=\"sig-name descname\"><span class=\"pre\">wall_tangents</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Unit hub and shroud tangents at the ends of one span line.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.meridional.</span></span><span class=\"sig-name descname\"><span class=\"pre\">MeridionalPassage</span></span></dt><dd><p>Paired hub and shroud curves, in <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> metres, inlet to outlet.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.area\">\n<span class=\"sig-name descname\"><span class=\"pre\">area</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Area of the surface the span line sweeps round the axis [m\u00b2].</p><p>That is the frustum <code class=\"docutils literal notranslate\"><span class=\"pre\">pi*(r_hub</span> <span class=\"pre\">+</span> <span class=\"pre\">r_shroud)*height</span></code>: an annulus\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pi*(r_s\u00b2</span> <span class=\"pre\">-</span> <span class=\"pre\">r_h\u00b2)</span></code> where the span line is radial, a cylinder\n<code class=\"docutils literal notranslate\"><span class=\"pre\">2*pi*r*b</span></code> where it is axial. It is the flow area where the flow\ncrosses the span line square, which is what a span line is drawn for.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.surface\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.surface\">\n<span class=\"sig-name descname\"><span class=\"pre\">surface</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_theta</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">160</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Cartesian points of <code class=\"docutils literal notranslate\"><span class=\"pre\">wall</span></code> revolved about +x, shape <code class=\"docutils literal notranslate\"><span class=\"pre\">(N,</span> <span class=\"pre\">n_theta,</span> <span class=\"pre\">3)</span></code>.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage._span_ends\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage._span_ends\">\n<span class=\"sig-name descname\"><span class=\"pre\">_span_ends</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.rotating\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.rotating\">\n<span class=\"sig-name descname\"><span class=\"pre\">rotating</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Whether <code class=\"docutils literal notranslate\"><span class=\"pre\">wall</span></code> turns with the shaft, at the stored stations or at <code class=\"docutils literal notranslate\"><span class=\"pre\">fraction</span></code>.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.end\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.end\">\n<span class=\"sig-name descname\"><span class=\"pre\">end</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">which</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">'inlet'</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">'outlet'</span></code> end, as an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">AnnulusEnd</span></code>.</p></dd>", "a[href=\"#pyskyfire-common-meridional-meridionalpassage\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.meridional.MeridionalPassage<a class=\"headerlink\" href=\"#pyskyfire-common-meridional-meridionalpassage\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.with_clearance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.with_clearance\">\n<span class=\"sig-name descname\"><span class=\"pre\">with_clearance</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">clearance</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'shroud'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>This passage with <code class=\"docutils literal notranslate\"><span class=\"pre\">wall</span></code> moved a distance <code class=\"docutils literal notranslate\"><span class=\"pre\">clearance</span></code> towards the other.</p><p>This is the boundary a blade is built to, not the wetted wall: the gap\nbetween the two is the clearance. The pairing, motion and recorded\nclearances are kept.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.clearance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.clearance\">\n<span class=\"sig-name descname\"><span class=\"pre\">clearance</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The clearances recorded for <code class=\"docutils literal notranslate\"><span class=\"pre\">blade</span></code>, as a tuple.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.hydraulic_diameter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.hydraulic_diameter\">\n<span class=\"sig-name descname\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">4A/P</span></code> over both walls [m], which for an annulus is twice its height.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.sample\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.sample\">\n<span class=\"sig-name descname\"><span class=\"pre\">sample</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span_fraction</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> at station <code class=\"docutils literal notranslate\"><span class=\"pre\">fraction</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">span_fraction</span></code> (0 hub, 1 shroud).</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.stations\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.stations\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">stations</span></span></dt><dd><p>Station fractions: the hub\u2019s arc length, normalised to 0..1.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage._interpolate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage._interpolate\">\n<span class=\"sig-name descname\"><span class=\"pre\">_interpolate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">curve</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.height\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.height\">\n<span class=\"sig-name descname\"><span class=\"pre\">height</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Span-line length [m], at the stored stations or at <code class=\"docutils literal notranslate\"><span class=\"pre\">fraction</span></code>.</p></dd>", "a[href=\"#pyskyfire.common.meridional.MeridionalPassage.__post_init__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage.__post_init__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__post_init__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
